class Solution {
    public long nthSmallest(long n, int k) {
        // Step 1: Pascal's table; C(50,25) ~ 1.26e14 needs long
        long[][] comb = new long[51][51];
        for (int i = 0; i <= 50; i++) {
            comb[i][0] = 1L;
            comb[i][i] = 1L;
            for (int j = 1; j < i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }

        long ans = 0L;
        // Step 2: walk bit positions from the top; answer < 2^50
        for (int pos = 49; pos >= 0 && k > 0; pos--) {
            // numbers with a 0 here and k ones below
            long cnt = comb[pos][k];
            if (n > cnt) {
                // Step 3: rank n is past that block, so this bit is 1
                ans |= 1L << pos;
                n -= cnt;
                k--;
            }
        }
        return ans;
    }
}

