class Solution {
public:
    // C(n, k) by the multiplicative formula; fits long long up to C(60, 30)
    long long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        if (k > n - k) k = n - k;
        long long res = 1;
        for (int i = 1; i <= k; i++) {
            res = res * (n - k + i) / i;
        }
        return res;
    }

    long long nthSmallest(long long n, int k) {
        n--;                 // 0-based rank
        long long ans = 0;
        int prev = 60;

        // Step 1: place the ones from the highest to the lowest
        for (int i = k; i >= 1; i--) {
            // Step 2: binary-search the highest position c with comb(c, i) <= rank,
            // i.e. the rank is past every number whose top remaining one is below c
            int lo = i - 1, hi = prev - 1;
            int c = i - 1;
            while (lo <= hi) {
                int mid = (lo + hi) >> 1;
                long long val = comb(mid, i);
                if (val <= n) {
                    c = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            // Step 3: set that bit, skip the comb(c, i) numbers below it
            ans |= (1LL << c);
            n -= comb(c, i);
            prev = c;
        }
        return ans;
    }
};

