var nthSmallest = function(n, k) {
    // C(N, K); every intermediate value stays below 2^53, so doubles are exact
    const comb = (N, K) => {
        if (K < 0 || K > N) return 0;
        if (K > N - K) K = N - K;
        let res = 1;
        for (let i = 0; i < K; i++) {
            res = res * (N - i) / (i + 1);
        }
        return res;
    };

    let ans = 0;
    // Step 1: walk bit positions from the top; answer < 2^50
    for (let pos = 49; pos >= 0; pos--) {
        if (k === 0) break;
        // Step 2: numbers with a 0 here and k ones below
        const c = comb(pos, k);
        if (n > c) {
            // Step 3: rank n is past that block, so this bit is 1
            ans += (2 ** pos);
            n -= c;
            k--;
        }
    }
    return ans;
};

